import pathlib,struct,base64,tempfile,os
def checksum(data):
    if len(data)%2:data+=b'\x00'
    total=sum(struct.unpack('!'+str(len(data)//2)+'H',data))
    while total>>16:total=(total&65535)+(total>>16)
    return (~total)&65535
def ipv4(packet):
    if len(packet)<20 or packet[0]>>4!=4:raise ValueError('invalid IPv4 header')
    ihl=(packet[0]&15)*4;total=struct.unpack('!H',packet[2:4])[0]
    if ihl<20 or ihl>len(packet) or not ihl<=total<=len(packet):raise ValueError('invalid IPv4 lengths')
    if checksum(packet[:ihl])!=0:raise ValueError('IPv4 checksum mismatch')
    if struct.unpack('!H',packet[6:8])[0]&0x3fff:raise ValueError('fragmented IPv4 unsupported')
    return packet[:total],ihl
def publish(source,output,data):
    source=pathlib.Path(source).resolve();target=pathlib.Path(output).resolve()
    if source==target:raise ValueError('input/output must differ')
    fd,name=tempfile.mkstemp(prefix='.packet-',dir=target.parent)
    try:
        with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
        os.replace(name,target)
    finally:
        if os.path.exists(name):os.unlink(name)

def execute(source,output):
    data=base64.b64decode(pathlib.Path(source).read_text(),validate=True)
    if len(data)<24:raise ValueError('short pcap')
    if data[:4]==bytes.fromhex('d4c3b2a1'):order='<'
    elif data[:4]==bytes.fromhex('a1b2c3d4'):order='>'
    else:raise ValueError('microsecond pcap required')
    major,minor,zone,sigfigs,snap,link=struct.unpack(order+'HHIIII',data[4:24])
    if (major,minor)!=(2,4) or link!=1:raise ValueError('Ethernet pcap 2.4 required')
    result=bytes.fromhex('d4c3b2a1')+struct.pack('<HHIIII',2,4,0,0,65535,101);offset=24;count=0
    while offset<len(data):
        if offset+16>len(data):raise ValueError('short record header')
        sec,usec,size,wire=struct.unpack(order+'IIII',data[offset:offset+16]);offset+=16
        if usec>=1000000 or size!=wire or size>snap or offset+size>len(data):raise ValueError('truncated or invalid record')
        frame=data[offset:offset+size];offset+=size
        if len(frame)<14 or frame[12:14]!=bytes.fromhex('0800'):raise ValueError('Ethernet IPv4 required')
        outer,ihl=ipv4(frame[14:])
        if outer[9]!=47 or len(outer)<ihl+4:raise ValueError('GRE IPv4 required')
        flags,protocol=struct.unpack('!HH',outer[ihl:ihl+4])
        if flags!=0 or protocol!=0x0800:raise ValueError('only unkeyed GRE v0 IPv4 supported')
        inner,inner_ihl=ipv4(outer[ihl+4:])
        if len(inner)!=len(outer)-ihl-4:raise ValueError('inner GRE payload length mismatch')
        result+=struct.pack('<IIII',sec,usec,len(inner),len(inner))+inner;count+=1
    publish(source,output,result);return count
```

原理补充：
GRE 在外层 IP 中加入 GRE 头和内层报文，使一种协议可以经另一网络转发。两端负责封装、解封装；中间网络只需能转发外层 IP。基本 GRE 不提供加密或可靠重传，需核对协议放行、路由和封装后的 MTU。

