def execute(source,output):
    original=bytes.fromhex(pathlib.Path(source).read_text());packet,ihl=ipv4(original)
    if len(packet)!=len(original):raise ValueError('trailing data after IPv4 packet')
    if packet[9]!=17 or len(packet)<ihl+8:raise ValueError('complete UDP datagram required')
    body=bytearray(packet[ihl:]);length=struct.unpack('!H',body[4:6])[0]
